class Solution(object):
    def isCircularSentence(self, sentence):
        """
        :type sentence: str
        :rtype: bool
        """
        s = sentence.split()
        for i in range(len(s) - 1):
            if s[i][-1] != s[i + 1][0]:
                return False
        if s[0][0] != s[-1][-1]:
            return False
        return True
